function productForm() {
  $('#view').innerHTML=`<div class="panel"><div class="panel-head"><h2>Novo produto</h2><button class="add-btn" data-go="products">Voltar à lista</button></div><form id="product-form" class="form-grid"><label>Nome<input name="nome" required></label><label>Código<input name="codigo"></label><label>Categoria<select name="categoria_id"><option value="">Selecione</option>${lookups.categories.map(x=>`<option value="${x.id}">${esc(x.nome)}</option>`).join('')}</select></label><label>Fornecedor<select name="fornecedor_id"><option value="">Selecione</option>${lookups.suppliers.map(x=>`<option value="${x.id}">${esc(x.nome)}</option>`).join('')}</select></label><label>Unidade de compra<select name="unidade_compra">${units()}</select></label><label>Unidade de consumo<select name="unidade_consumo">${units()}</select></label><label>Fator de conversão<input name="fator_conversao" type="number" step=".0001" min=".0001" value="1" required><small>Unidades de consumo contidas em uma unidade de compra, quando a conversão não for kg/g ou l/ml.</small></label><label>Rendimento (%)<input name="rendimento_percentual" type="number" step=".01" min=".01" max="100" value="100"></label><label>Preço atual<input name="preco_atual" type="number" step=".01" min="0" required></label><label>Estoque mínimo<input name="estoque_minimo" type="number" step=".001" min="0" value="0"></label><label>Estoque máximo<input name="estoque_maximo" type="number" step=".001" min="0"></label><label>Validade padrão (dias)<input name="validade_padrao_dias" type="number" step="1" min="1"></label><button class="primary wide">Salvar produto</button></form></div>`;
  bindGo(); $('#product-form').onsubmit=async e=>{e.preventDefault();try{await api('products',{method:'POST',body:JSON.stringify(Object.fromEntries(new FormData(e.target)))});toast('Produto salvo');load('products');}catch(x){toast(x.message);}};
}
async function recipes() {
  const d=await api('recipes'); records.recipes=d.items;
  $('#view').innerHTML=`<div class="panel"><div class="panel-head"><div><h2>Fichas técnicas</h2><p class="muted">As fichas existentes podem ser consultadas sem alterar os dados.</p></div><button class="add-btn" id="new-recipe">+ Nova ficha</button></div>${table(d.items,['nome','tipo','porcoes','custo_total','custo_porcao','status'],row=>`<button class="small-btn" data-recipe="${row.id}">Ver ficha</button>`)}</div>`;
  $('#new-recipe').onclick=recipeForm; document.querySelectorAll('[data-recipe]').forEach(b=>b.onclick=()=>recipeDetail(b.dataset.recipe));
}
function recipeDetail(id) {
  const r=records.recipes.find(x=>String(x.id)===String(id)); if(!r)return;
  const ingredients=r.itens||[];
  const rows=ingredients.map(i=>({...i,custo_linha:Number(i.quantidade_liquida)*Number(i.preco_atual)}));
  const foodCost=Number(r.preco_venda)>0?Number(r.custo_porcao)/Number(r.preco_venda)*100:0;
  $('#view').innerHTML=`<div class="panel"><div class="panel-head"><div><h2>${esc(r.nome)}</h2><p class="muted">Ficha técnica em modo de consulta — nenhum campo pode ser editado aqui.</p></div><button class="add-btn" data-go="recipes">Voltar à lista</button></div>
    <div class="detail-grid">${detail('Código',r.codigo)}${detail('Categoria',r.categoria)}${detail('Tipo',r.tipo)}${detail('Status',r.status)}${detail('Rendimento',`${r.rendimento_total} ${r.unidade_rendimento}`)}${detail('Porções',r.porcoes)}${detail('Tamanho da porção',r.tamanho_porcao)}${detail('Custo total',cash(r.custo_total))}${detail('Custo por porção',cash(r.custo_porcao))}${detail('Preço de venda',cash(r.preco_venda))}${detail('Custo sobre venda',Number(r.preco_venda)>0?`${foodCost.toFixed(1)}%`:'Não informado')}</div>
    <h3>Ingredientes</h3>${table(rows,['produto','quantidade_liquida','unidade_consumo','preco_atual','custo_linha'])}<h3>Modo de preparo</h3><div class="text-block">${esc(r.modo_preparo||'Modo de preparo não informado.').replace(/\n/g,'<br>')}</div></div>`; bindGo();
}
function recipeForm() {
  let n=0;
  $('#view').innerHTML=`<div class="panel"><div class="panel-head"><h2>Nova ficha técnica</h2><button class="add-btn" data-go="recipes">Voltar à lista</button></div><form id="recipe-form" class="form-grid"><label>Nome do preparo<input name="nome" required></label><label>Código<input name="codigo"></label><label>Categoria<select name="categoria_id"><option value="">Selecione</option>${lookups.categories.map(x=>`<option value="${x.id}">${esc(x.nome)}</option>`).join('')}</select></label><label>Tipo<select name="tipo"><option>prato</option><option>molho</option><option>base</option><option>sobremesa</option></select></label><label>Rendimento total<input name="rendimento_total" type="number" step=".001" required></label><label>Unidade do rendimento<select name="unidade_rendimento">${units()}</select></label><label>Porções<input name="porcoes" type="number" step=".001" value="1" required></label><label>Tamanho da porção<input name="tamanho_porcao" type="number" step=".001"></label><label>Preço de venda<input name="preco_venda" type="number" step=".01"></label><label class="wide">Modo de preparo<textarea name="modo_preparo"></textarea></label><div class="wide"><div class="panel-head"><h3>Ingredientes</h3><button type="button" class="add-btn" id="add-item">+ Ingrediente</button></div><div id="items"></div></div><button class="primary wide">Salvar ficha</button></form></div>`;
  bindGo(); const add=()=>{const i=n++;$('#items').insertAdjacentHTML('beforeend',`<div class="recipe-item"><select name="p${i}" required>${lookups.products.map(x=>`<option value="${x.id}">${esc(x.nome)} (${cash(x.preco_atual)}/${esc(x.unidade_consumo)})</option>`).join('')}</select><input name="q${i}" type="number" step=".001" min=".001" placeholder="Quantidade" required><button type="button" class="icon-btn" aria-label="Remover ingrediente" onclick="this.parentElement.remove()">×</button></div>`);};
  $('#add-item').onclick=add; add();
  $('#recipe-form').onsubmit=async e=>{e.preventDefault();const form=new FormData(e.target),items=[];for(let i=0;i<n;i++)if(form.get(`p${i}`)&&form.get(`q${i}`))items.push({produto_id:form.get(`p${i}`),quantidade:form.get(`q${i}`)});const data=Object.fromEntries(form);data.itens=items;try{await api('recipes',{method:'POST',body:JSON.stringify(data)});toast('Ficha salva');load('recipes');}catch(x){toast(x.message);}};
}
