function purchaseForm(){let next=0;$('#view').innerHTML=`<div class="panel"><div class="panel-head"><h2>Registrar compra</h2><button class="add-btn" data-go="purchases">Voltar</button></div><form id="purchase-form" class="form-grid"><label>Fornecedor<select name="fornecedor_id" required>${lookups.suppliers.map(x=>`<option value="${x.id}">${esc(x.nome)}</option>`).join('')}</select></label><label>Data<input name="data_compra" type="datetime-local" value="${new Date(Date.now()-new Date().getTimezoneOffset()*60000).toISOString().slice(0,16)}" required></label><label>Nota / referência<input name="referencia"></label><label>Desconto total<input name="desconto_total" type="number" min="0" step=".01" value="0"></label><label>Frete total<input name="frete_total" type="number" min="0" step=".01" value="0"></label><label class="wide">Observações<textarea name="observacoes"></textarea></label><div class="wide"><div class="panel-head"><h3>Itens</h3><button type="button" class="add-btn" id="add-purchase-item">+ Item</button></div><div id="purchase-lines"></div></div><button class="primary wide">Salvar compra como rascunho</button></form></div>`;bindGo();const add=()=>{const i=next++;$('#purchase-lines').insertAdjacentHTML('beforeend',`<div class="recipe-item purchase-line"><select name="product${i}">${lookups.products.map(p=>`<option value="${p.id}">${esc(p.nome)} (preço cadastrado ${cash(p.preco_atual)} / ${esc(p.unidade_compra)})</option>`).join('')}</select><input name="qty${i}" type="number" min=".001" step=".001" placeholder="Quantidade" required><input name="price${i}" type="number" min="0" step=".0001" placeholder="Preço por ${esc(lookups.products[0]?.unidade_compra||'unidade')}" required><button class="icon-btn" type="button" onclick="this.parentElement.remove()">×</button></div>`);};$('#add-purchase-item').onclick=add;add();$('#purchase-form').onsubmit=async e=>{e.preventDefault();const form=new FormData(e.target),d=Object.fromEntries(form);d.data_compra=d.data_compra.replace('T',' ')+':00';d.itens=[];for(let i=0;i<next;i++){const product=form.get(`product${i}`),qty=form.get(`qty${i}`),price=form.get(`price${i}`);if(product&&qty){const productInfo=lookups.products.find(p=>String(p.id)===product);d.itens.push({produto_id:product,quantidade:qty,unidade:productInfo?.unidade_compra,preco_unitario:price});}}try{await api('purchases',{method:'POST',body:JSON.stringify(d)});toast('Compra salva como rascunho');purchases();}catch(err){toast(err.message);}};}
