async function inventory(){const d=await api('inventory');$('#view').innerHTML=`<div class="panel"><div class="panel-head"><div><h2>Inventários</h2><p class="muted">Crie uma contagem, registre quantidades físicas e aprove para gerar ajustes.</p></div><button class="add-btn" id="new-inventory">Iniciar contagem</button></div>${table(d.items,['id','local','status','iniciado_em','usuario'],row=>`<button class="small-btn" data-inventory="${row.id}">Abrir</button>`)}</div>`;$('#new-inventory').onclick=async()=>{try{const r=await api('inventory',{method:'POST',body:JSON.stringify({local_id:1})});inventoryDetail(r.id);}catch(e){toast(e.message);}};document.querySelectorAll('[data-inventory]').forEach(b=>b.onclick=()=>inventoryDetail(b.dataset.inventory));}
