async function buffet(){const d=await api('buffet');$('#view').innerHTML=`<div class="panel"><div class="panel-head"><div><h2>Buffet e café da manhã</h2><p class="muted">Registre preparado, servido, sobra reaproveitável e descarte em campos separados.</p></div></div><form id="buffet-form" class="form-grid"><label>Data e hora<input type="datetime-local" name="data_operacao" value="${new Date(Date.now()-new Date().getTimezoneOffset()*60000).toISOString().slice(0,16)}"></label><label>Turno<input name="turno" required placeholder="Café / almoço / jantar"></label><label>Setor<input name="setor" required></label><label>Produto (opcional)<select name="produto_id"><option value="">Selecione</option>${lookups.products.map(p=>`<option value="${p.id}">${esc(p.nome)}</option>`).join('')}</select></label><label>Ficha (opcional)<select name="ficha_id"><option value="">Selecione</option>${records.recipes.map(r=>`<option value="${r.id}">${esc(r.nome)}</option>`).join('')}</select></label><label>Unidade<select name="unidade">${units()}</select></label><label>Quantidade preparada<input name="quantidade_preparada" type="number" step=".001" min="0" value="0"></label><label>Quantidade servida/estimada<input name="quantidade_servida" type="number" step=".001" min="0" value="0"></label><label>Sobra reaproveitável<input name="sobra_reaproveitavel" type="number" step=".001" min="0" value="0"></label><label>Descarte<input name="descarte" type="number" step=".001" min="0" value="0"></label><label>Motivo do descarte<input name="motivo"></label><label>Custo estimado<input name="custo_estimado" type="number" step=".01" min="0" value="0"></label><label class="wide">Observações<textarea name="observacoes"></textarea></label><button class="primary wide">Registrar operação</button></form></div><div class="panel"><h2>Registros recentes</h2>${table(d.items,['data_operacao','turno','setor','produto','quantidade_preparada','quantidade_servida','sobra_reaproveitavel','descarte','unidade','custo_estimado'])}</div>`;$('#buffet-form').onsubmit=async e=>{e.preventDefault();const d=Object.fromEntries(new FormData(e.target));d.data_operacao=d.data_operacao.replace('T',' ')+':00';try{await api('buffet',{method:'POST',body:JSON.stringify(d)});toast('Registro salvo');buffet();}catch(err){toast(err.message);}};}
