async function reports() {
  const today=new Date(),fromDate=new Date(today);fromDate.setDate(today.getDate()-29);
  const to=isoDate(today),from=isoDate(fromDate);
  $('#view').innerHTML=`<div class="panel"><div class="panel-head"><div><h2>Relatório geral de gestão</h2><p class="muted">Desperdícios no período selecionado e indicadores atuais de produtos, fichas técnicas e fornecedores.</p></div></div><form id="report-filter" class="filter-row"><label>Desperdícios de<input type="date" name="from" value="${from}"></label><label>Até<input type="date" name="to" value="${to}"></label><button class="primary" id="generate-report">Gerar relatório</button></form><div id="report-message" class="report-message" role="status">Selecione o período e clique em “Gerar relatório”.</div><div id="report-content"></div></div>`;
  $('#report-filter').onsubmit=async e=>{e.preventDefault();const button=$('#generate-report');button.disabled=true;button.textContent='Gerando…';$('#report-message').textContent='Consultando e organizando os dados…';$('#report-message').classList.remove('error-text');try{await renderReport(new FormData(e.target));$('#report-message').textContent='Relatório gerado com sucesso.';}catch(error){$('#report-message').textContent=`Não foi possível gerar o relatório: ${error.message}`;$('#report-message').classList.add('error-text');}finally{button.disabled=false;button.textContent='Gerar relatório';}};
  await $('#report-filter').requestSubmit();
}
async function renderReport(form) {
  const params=new URLSearchParams(Object.fromEntries(form));const d=await api(`waste_report&${params}`);
  currentReport=d; $('#report-content').innerHTML=reportMarkup(d,true);
  $('#save-report').onclick=saveCurrentReport;$('#export-report').onclick=()=>exportReport(d,'relatorio_gestao');$('#print-report').onclick=()=>window.print();
}
function legacyReportMarkup(d,withActions=false){return `${withActions?'<div class="report-actions no-print"><button class="primary" id="save-report">Salvar no histórico</button><button class="add-btn" id="export-report">Exportar CSV</button><button class="add-btn" id="print-report">Imprimir / Salvar PDF</button></div>':''}<p class="muted">Período das perdas: ${dateOnly(d.from)} a ${dateOnly(d.to)}</p><div class="card-grid"><div class="card"><span class="muted">Valor estimado perdido</span><div class="metric">${cash(d.summary.total_valor)}</div></div><div class="card"><span class="muted">Ocorrências de desperdício</span><div class="metric">${Number(d.summary.quantidade_registros||0)}</div></div><div class="card"><span class="muted">Produtos ativos</span><div class="metric">${d.counts.produtos}</div></div><div class="card"><span class="muted">Fornecedores ativos</span><div class="metric">${d.counts.fornecedores}</div></div><div class="card"><span class="muted">Fichas técnicas ativas</span><div class="metric">${d.counts.fichas}</div></div><div class="card"><span class="muted">Custo médio das até 100 primeiras fichas</span><div class="metric">${cash(d.recipes.custo_medio)}</div></div></div><div class="report-grid">${barChart('Maiores perdas por produto',d.byProduct,'produto','valor')}${barChart('Perdas por motivo',d.byReason,'motivo','valor')}${barChart('Desperdício por dia',d.byDay,'dia','valor')}${barChart('Produtos por categoria',d.productsByCategory,'categoria','quantidade')}</div><h3>Ranking de produtos desperdiçados</h3>${table(d.byProduct,['produto','ocorrencias','valor'])}<h3>Resumo por motivo</h3>${table(d.byReason,['motivo','ocorrencias','valor'])}<h3>Fornecedores e produtos vinculados</h3>${table(d.suppliersByProducts,['fornecedor','produtos_vinculados'])}<h3>Fichas com maior custo total (até 10)</h3>${table(d.recipes.mais_custosas,['nome','tipo','custo_total','custo_porcao'])}`;}
function reportMarkup(d,withActions=false){const o=d.operations||{};return `${legacyReportMarkup(d,withActions)}<h3>Operação no período</h3><div class="card-grid"><div class="card"><span class="muted">Compra recebida (valor bruto)</span><div class="metric">${cash(o.compras?.valor_bruto)}</div><small>${Number(o.compras?.quantidade||0)} compra(s)</small></div><div class="card"><span class="muted">Descarte informado no buffet</span><div class="metric">${Number(o.buffet?.descarte||0).toLocaleString('pt-BR')}</div><small>${cash(o.buffet?.custo)} · ${Number(o.buffet?.quantidade||0)} registro(s)</small></div><div class="card"><span class="muted">Quebras patrimoniais</span><div class="metric">${cash(o.quebras?.valor)}</div><small>${Number(o.quebras?.quantidade||0)} ocorrência(s)</small></div><div class="card"><span class="muted">Produção planejada / realizada</span><div class="metric">${Number(o.producao?.planejada||0).toLocaleString('pt-BR')} / ${Number(o.producao?.produzida||0).toLocaleString('pt-BR')}</div><small>${Number(o.producao?.quantidade||0)} registro(s)</small></div><div class="card"><span class="muted">Produtos abaixo do mínimo (saldo atual)</span><div class="metric">${Number(o.estoque?.itens_abaixo_minimo||0)}</div></div></div><p class="muted">Compra exibida pelo valor bruto dos itens, sem rateio de frete/descontos. Estoque é posição atual, não posição histórica no período. Quantidades do buffet e produção mantêm suas unidades de origem.</p>`;}
async function saveCurrentReport(){if(!currentReport)return;const title=prompt('Nome para este relatório:','Relatório de gestão');if(title===null)return;try{const result=await api('report_history',{method:'POST',body:JSON.stringify({titulo:title,report:currentReport})});toast(`Relatório salvo no histórico (#${result.id})`);}catch(error){toast(`Não foi possível salvar: ${error.message}`);}}
function exportReport(report,title='relatorio'){const rows=[['Seção','Indicador','Detalhe','Valor'],['Resumo','Período',`${report.from} a ${report.to}`,''],['Resumo','Valor total desperdiçado','',report.summary.total_valor],['Resumo','Ocorrências de desperdício','',report.summary.quantidade_registros],['Resumo','Produtos ativos','',report.counts.produtos],['Resumo','Fornecedores ativos','',report.counts.fornecedores],['Resumo','Fichas ativas','',report.counts.fichas],['Resumo','Custo médio das fichas (amostra)','',report.recipes.custo_medio]];for(const x of report.byProduct||[])rows.push(['Desperdícios por produto',x.produto,`${x.ocorrencias} ocorrência(s)`,x.valor]);for(const x of report.byReason||[])rows.push(['Desperdícios por motivo',x.motivo,`${x.ocorrencias} ocorrência(s)`,x.valor]);for(const x of report.byDay||[])rows.push(['Desperdícios por dia',x.dia,'',x.valor]);for(const x of report.productsByCategory||[])rows.push(['Produtos por categoria',x.categoria,'',x.quantidade]);for(const x of report.suppliersByProducts||[])rows.push(['Fornecedores',x.fornecedor,'Produtos vinculados',x.produtos_vinculados]);for(const x of report.recipes?.mais_custosas||[])rows.push(['Fichas técnicas',x.nome,`${x.tipo} · custo por porção ${x.custo_porcao}`,x.custo_total]);const csv='\uFEFF'+rows.map(row=>row.map(cell=>`"${String(cell??'').replace(/"/g,'""')}"`).join(';')).join('\r\n');const url=URL.createObjectURL(new Blob([csv],{type:'text/csv;charset=utf-8'}));const link=document.createElement('a');link.href=url;link.download=`${safeFilename(title)}.csv`;link.click();URL.revokeObjectURL(url);}
function safeFilename(value){return String(value||'relatorio').normalize('NFD').replace(/[\u0300-\u036f]/g,'').replace(/[^a-zA-Z0-9_-]+/g,'_').replace(/^_|_$/g,'').toLowerCase()||'relatorio';}
function barChart(title,rows,labelKey,valueKey){const values=(rows||[]).slice(-10);if(!values.length)return `<div class="chart-card"><h3>${esc(title)}</h3><p class="muted">Sem dados para o período selecionado.</p></div>`;const max=Math.max(...values.map(r=>Number(r[valueKey]||0)),1);return `<div class="chart-card"><h3>${esc(title)}</h3>${values.map(row=>`<div class="bar-row"><span title="${esc(row[labelKey])}">${esc(row[labelKey])}</span><div class="bar-track"><i style="width:${Math.max(2,Number(row[valueKey]||0)/max*100)}%"></i></div><b>${valueKey==='valor'?cash(row[valueKey]):Number(row[valueKey]||0).toLocaleString('pt-BR')}</b></div>`).join('')}</div>`;}
async function filters(){
  $('#view').innerHTML=`<div class="panel"><div class="panel-head"><div><h2>Filtros e busca</h2><p class="muted">Pesquise no banco por seção. Os resultados são consultados no servidor e limitados aos 100 primeiros, evitando carregar o banco inteiro de uma vez.</p></div></div><form id="global-filter" class="filter-row"><label>Seção<select name="type"><option value="products">Produtos e alimentos</option><option value="suppliers">Fornecedores</option><option value="recipes">Fichas e pratos</option><option value="waste">Desperdícios</option></select></label><label class="filter-query">Nome, código, categoria, motivo…<input name="q" placeholder="Digite o que deseja localizar"></label><label class="waste-date">De<input type="date" name="from"></label><label class="waste-date">Até<input type="date" name="to"></label><button class="primary">Buscar</button></form><div id="filter-message" class="report-message"></div><div id="filter-results"></div></div>`;
  const form=$('#global-filter');form.querySelector('[name="from"]').value='';form.querySelector('[name="to"]').value='';
  const syncDates=()=>document.querySelectorAll('.waste-date').forEach(label=>label.hidden=form.type.value!=='waste');form.type.onchange=syncDates;syncDates();
  form.onsubmit=async event=>{event.preventDefault();const params=new URLSearchParams(Object.fromEntries(new FormData(form)));$('#filter-message').textContent='Pesquisando…';try{const result=await api(`search&${params}`);const cols={products:['nome','codigo','categoria','unidade_consumo','preco_atual','fornecedor'],suppliers:['nome','documento','telefone','contato','produtos_vinculados'],recipes:['nome','tipo','categoria','porcoes','custo_total','status'],waste:['data_registro','produto','quantidade','unidade','etapa','motivo','valor_estimado']};$('#filter-results').innerHTML=table(result.items,cols[form.type.value]);$('#filter-message').textContent=`${result.items.length} resultado(s) exibido(s). Limite desta busca: ${result.limit}.`; }catch(error){$('#filter-message').textContent=`Falha na busca: ${error.message}`;$('#filter-message').classList.add('error-text');}};
}
async function reportHistory(page=1){
  reportPage=page;const data=await api(`report_history&page=${page}`);
  $('#view').innerHTML=`<div class="panel"><div class="panel-head"><div><h2>Histórico de relatórios</h2><p class="muted">Relatórios salvos ficam disponíveis para consulta e exportação posterior.</p></div><button class="add-btn" data-go="reports">Gerar novo relatório</button></div>${table(data.items,['titulo','data_inicio','data_fim','criado_em','usuario'],row=>`<button class="small-btn" data-report-id="${row.id}">Abrir / exportar</button>`)}<div class="pager"><span>${data.total} relatório(s) salvo(s) · página ${data.page} de ${Math.max(1,Math.ceil(data.total/data.perPage))}</span><div><button class="add-btn" id="report-prev" ${page<=1?'disabled':''}>Anterior</button><button class="add-btn" id="report-next" ${page>=Math.ceil(data.total/data.perPage)?'disabled':''}>Próxima</button></div></div><div id="history-detail"></div></div>`;
  bindGo();document.querySelectorAll('[data-report-id]').forEach(button=>button.onclick=()=>openSavedReport(button.dataset.reportId));$('#report-prev').onclick=()=>reportHistory(Math.max(1,page-1));$('#report-next').onclick=()=>reportHistory(page+1);const savedId=sessionStorage.getItem('restaurant-report-id');if(savedId)openSavedReport(savedId);
}
async function openSavedReport(id){try{sessionStorage.setItem('restaurant-report-id',id);const item=await api(`report_history_item&id=${encodeURIComponent(id)}`);const target=$('#history-detail');target.innerHTML=`<div class="saved-report-head"><div><h2>${esc(item.titulo)}</h2><p class="muted">Salvo em ${dateTime(item.criado_em)} por ${esc(item.usuario)} · período ${dateOnly(item.data_inicio)} a ${dateOnly(item.data_fim)}</p></div><div class="quick-links no-print"><button class="add-btn" id="saved-export">Exportar CSV</button><button class="add-btn" id="saved-print">Imprimir / Salvar PDF</button></div></div>${reportMarkup(item.report,false)}`;$('#saved-export').onclick=()=>exportReport(item.report,item.titulo);$('#saved-print').onclick=()=>window.print();target.scrollIntoView({behavior:'smooth',block:'start'});}catch(error){toast(`Não foi possível abrir o relatório: ${error.message}`);}}
function table(rows,columns,action) {
  if(!rows?.length)return '<p class="muted empty-state">Nenhum registro encontrado.</p>';
  const labels={data_registro:'Data',data_inicio:'De',data_fim:'Até',criado_em:'Salvo em',titulo:'Nome do relatório',usuario:'Salvo por',produto:'Produto',quantidade:'Quantidade',unidade:'Unidade',motivo:'Motivo',valor_estimado:'Valor estimado',nome:'Nome',categoria:'Categoria',unidade_consumo:'Unidade',preco_atual:'Preço atual',fornecedor:'Fornecedor',documento:'Documento',telefone:'Telefone',contato:'Contato',produtos_vinculados:'Produtos vinculados',marca:'Marca',unidade_compra:'Unidade de compra',tipo:'Tipo',porcoes:'Porções',custo_total:'Custo total',custo_porcao:'Custo / porção',status:'Status',etapa:'Etapa',ocorrencias:'Ocorrências',valor:'Valor',quantidade_liquida:'Qtd. líquida',custo_linha:'Custo do ingrediente'};
  return `<div class="table-wrap"><table><thead><tr>${columns.map(c=>`<th>${labels[c]||c}</th>`).join('')}${action?'<th>Ação</th>':''}</tr></thead><tbody>${rows.map(row=>`<tr>${columns.map(c=>`<td>${formatCell(c,row[c])}</td>`).join('')}${action?`<td>${action(row)}</td>`:''}</tr>`).join('')}</tbody></table></div>`;
}
function formatCell(key,value){if(value===null||value===undefined||value==='')return '—';if(['valor_estimado','preco_atual','custo_total','custo_porcao','custo_linha','valor'].includes(key))return cash(value);if(key==='data_registro'||key==='criado_em')return dateTime(value);if(key==='data_inicio'||key==='data_fim')return dateOnly(value);if(key==='quantidade_liquida'||key==='quantidade')return Number(value).toLocaleString('pt-BR');return esc(value);}
function detail(label,value){return `<div class="detail-item"><span>${esc(label)}</span><strong>${value===null||value===undefined||value===''?'—':esc(value)}</strong></div>`;}
function units(){return (lookups.units||[]).map(x=>`<option value="${esc(x.codigo)}">${esc(x.nome)}</option>`).join('');}
function cash(value){return Number(value||0).toLocaleString('pt-BR',{style:'currency',currency:'BRL'});}
function esc(value){return String(value??'').replace(/[&<>"']/g,char=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[char]));}
function isoDate(date){return `${date.getFullYear()}-${String(date.getMonth()+1).padStart(2,'0')}-${String(date.getDate()).padStart(2,'0')}`;}
function dateTime(value){if(!value)return '—';const date=new Date(String(value).replace(' ','T'));return Number.isNaN(date.getTime())?esc(value):date.toLocaleString('pt-BR');}
function dateOnly(value){if(!value)return '—';const [y,m,d]=value.split('-');return `${d}/${m}/${y}`;}
function bindGo(){document.querySelectorAll('[data-go]').forEach(button=>button.addEventListener('click',()=>load(button.dataset.go)));}
function applyNavigationRole(){const all=['dashboard','products','suppliers','recipes','purchases','stock','inventory','production','buffet','waste','breakages','reports','report_history','filters','settings','users'];const access={admin:all,gestor:all.filter(x=>x!=='users'),cozinha:['dashboard','recipes','production','buffet','waste','breakages','reports','report_history','filters'],compras:['dashboard','products','suppliers','purchases','stock','inventory','filters'],operacional:['dashboard','buffet','waste','breakages']};document.querySelectorAll('nav [data-view]').forEach(button=>button.hidden=!(access[currentUser?.perfil]||access.operacional).includes(button.dataset.view));}
function recipeDetail(id){
  const recipe=records.recipes.find(item=>String(item.id)===String(id));if(!recipe)return;
  const canManage=['admin','gestor'].includes(currentUser?.perfil);
  const rows=(recipe.itens||[]).map(item=>{
    const product=lookups.products.find(p=>String(p.id)===String(item.produto_id));
    const component=records.recipes.find(r=>String(r.id)===String(item.ficha_componente_id));
    const base=product?Number(product.preco_atual||0)/Math.max(productUnitFactor(product),.000001):component?Number(component.custo_total||0)/Math.max(Number(component.rendimento_total||1),.000001):0;
    return {...item,produto:product?.nome||component?.nome||'Item',unidade_consumo:product?.unidade_consumo||component?.unidade_rendimento||'',preco_atual:base,custo_linha:Number(item.quantidade_liquida||item.quantidade_bruta||0)*base};
  });
  const actions=canManage?`<div class="quick-links"><button class="add-btn" id="edit-recipe">Editar e criar nova versão</button>${recipe.status==='aprovada'?'':`<button class="primary" id="approve-recipe">Aprovar ficha</button>`}</div>`:'';
  $('#view').innerHTML=`<div class="panel"><div class="panel-head"><div><h2>${esc(recipe.nome)}</h2><p class="muted">Consulta da ficha técnica. Edição cria uma nova versão e retorna para rascunho.</p></div><button class="add-btn" data-go="recipes">Voltar à lista</button></div>${actions}<div class="detail-grid">${detail('Código',recipe.codigo)}${detail('Categoria',recipe.categoria)}${detail('Tipo',recipe.tipo)}${detail('Status',recipe.status)}${detail('Versão',recipe.versao)}${detail('Rendimento',`${recipe.rendimento_total} ${recipe.unidade_rendimento}`)}${detail('Porções',recipe.porcoes)}${detail('Tempo de preparo (min)',recipe.tempo_preparo_minutos)}${detail('Validade (h)',recipe.validade_horas)}${detail('Equipamentos',recipe.equipamentos)}${detail('Armazenamento',recipe.armazenamento)}${detail('Custo total',cash(recipe.custo_total))}${detail('Custo por porção',cash(recipe.custo_porcao))}${detail('Preço de venda',cash(recipe.preco_venda))}${detail('Aprovada em',dateTime(recipe.aprovada_em))}</div><h3>Ingredientes e sub-receitas</h3>${table(rows,['produto','quantidade_liquida','unidade_consumo','preco_atual','custo_linha'])}<h3>Modo de preparo</h3><div class="text-block">${esc(recipe.modo_preparo||'Não informado.').replace(/\n/g,'<br>')}</div><h3>Observações</h3><div class="text-block">${esc(recipe.observacoes||'—')}</div><div id="recipe-versions"></div></div>`;
  bindGo();$('#edit-recipe')?.addEventListener('click',()=>recipeForm(recipe));$('#approve-recipe')?.addEventListener('click',async()=>{try{await api('recipe_approve',{method:'POST',body:JSON.stringify({id:recipe.id})});toast('Ficha aprovada');load('recipes');}catch(error){toast(error.message);}});
  api(`recipe_versions&id=${recipe.id}`).then(result=>{const target=$('#recipe-versions');if(target&&result.items.length)target.innerHTML=`<h3>Versões anteriores</h3>${table(result.items,['versao','criado_em','usuario'])}`;}).catch(()=>{});
}
function productUnitFactor(product){const scale={kg:['massa',1000],g:['massa',1],l:['volume',1000],ml:['volume',1]};const purchase=scale[String(product.unidade_compra||'').toLowerCase()],consume=scale[String(product.unidade_consumo||'').toLowerCase()];return purchase&&consume&&purchase[0]===consume[0]?purchase[1]/consume[1]:Number(product.fator_conversao||1);}
function recipeForm(recipe=null){
  let next=0;const editing=Boolean(recipe);const canEdit=editing&&['admin','gestor'].includes(currentUser?.perfil);if(editing&&!canEdit){toast('Somente gestor ou administrador pode editar fichas.');return;}
  const values=recipe||{};
  $('#view').innerHTML=`<div class="panel"><div class="panel-head"><h2>${editing?'Nova versão da ficha':'Nova ficha técnica'}</h2><button class="add-btn" data-go="recipes">Voltar à lista</button></div><form id="recipe-form" class="form-grid">${editing?`<input type="hidden" name="id" value="${esc(values.id)}">`:''}<label>Nome<input name="nome" value="${esc(values.nome||'')}" required></label><label>Código<input name="codigo" value="${esc(values.codigo||'')}"></label><label>Categoria<select name="categoria_id"><option value="">Selecione</option>${lookups.categories.map(x=>`<option value="${x.id}" ${String(values.categoria_id)===String(x.id)?'selected':''}>${esc(x.nome)}</option>`).join('')}</select></label><label>Tipo<select name="tipo">${['prato','molho','base','sobremesa'].map(x=>`<option ${values.tipo===x?'selected':''}>${x}</option>`).join('')}</select></label><label>Rendimento total<input name="rendimento_total" type="number" min=".001" step=".001" value="${esc(values.rendimento_total||1)}" required></label><label>Unidade do rendimento<select name="unidade_rendimento">${units()}</select></label><label>Porções<input name="porcoes" type="number" min=".001" step=".001" value="${esc(values.porcoes||1)}" required></label><label>Tamanho da porção<input name="tamanho_porcao" type="number" min="0" step=".001" value="${esc(values.tamanho_porcao||'')}"></label><label>Preço de venda<input name="preco_venda" type="number" min="0" step=".01" value="${esc(values.preco_venda||0)}"></label><label>Tempo de preparo (min)<input name="tempo_preparo_minutos" type="number" min="0" step="1" value="${esc(values.tempo_preparo_minutos||'')}"></label><label>Validade (horas)<input name="validade_horas" type="number" min="0" step="1" value="${esc(values.validade_horas||'')}"></label><label>Equipamentos<input name="equipamentos" value="${esc(values.equipamentos||'')}"></label><label>Armazenamento<input name="armazenamento" value="${esc(values.armazenamento||'')}"></label><label class="wide">Modo de preparo<textarea name="modo_preparo">${esc(values.modo_preparo||'')}</textarea></label><label class="wide">Observações<textarea name="observacoes">${esc(values.observacoes||'')}</textarea></label><div class="wide"><div class="panel-head"><h3>Ingredientes</h3><button type="button" class="add-btn" id="add-item">+ Item</button></div><div id="items"></div></div><button class="primary wide">${editing?'Salvar nova versão':'Salvar ficha'}</button></form></div>`;
  const add=(item={})=>{const i=next++;const selected=item.produto_id?`p:${item.produto_id}`:item.ficha_componente_id?`f:${item.ficha_componente_id}`:'';$('#items').insertAdjacentHTML('beforeend',`<div class="recipe-item"><select name="ingredient${i}" required><option value="">Selecione produto ou sub-receita</option><optgroup label="Produtos">${lookups.products.map(p=>`<option value="p:${p.id}" ${selected===`p:${p.id}`?'selected':''}>${esc(p.nome)} (${esc(p.unidade_consumo)})</option>`).join('')}</optgroup><optgroup label="Sub-receitas">${lookups.recipes.filter(r=>String(r.id)!==String(recipe?.id)).map(r=>`<option value="f:${r.id}" ${selected===`f:${r.id}`?'selected':''}>${esc(r.nome)} (${esc(r.unidade_rendimento)})</option>`).join('')}</optgroup></select><input name="qty${i}" type="number" min=".001" step=".001" placeholder="Quantidade" value="${esc(item.quantidade_liquida||item.quantidade_bruta||'')}" required><input name="factor${i}" type="number" min=".0001" step=".0001" value="${esc(item.fator_correcao||1)}" title="Fator de correção"><button type="button" class="icon-btn" aria-label="Remover ingrediente" onclick="this.parentElement.remove()">×</button></div>`);};
  (values.itens?.length?values.itens:[{}]).forEach(add);$('#add-item').onclick=()=>add();bindGo();
  $('#recipe-form').onsubmit=async event=>{event.preventDefault();const form=new FormData(event.target),data=Object.fromEntries(form);data.itens=[];for(let i=0;i<next;i++){const selected=form.get(`ingredient${i}`),quantity=form.get(`qty${i}`);if(!selected||!quantity)continue;const [kind,id]=selected.split(':');data.itens.push({produto_id:kind==='p'?id:null,ficha_componente_id:kind==='f'?id:null,quantidade:quantity,fator_correcao:form.get(`factor${i}`)||1});}if(!data.itens.length){toast('Inclua ao menos um ingrediente.');return;}try{await api(editing?'recipe_update':'recipes',{method:'POST',body:JSON.stringify(data)});toast(editing?'Nova versão salva como rascunho':'Ficha salva como rascunho');load('recipes');}catch(error){toast(error.message);}};
}
async function inventoryDetail(id){
  try{
    const result=await api(`inventory_detail&id=${id}`);
    let target=$('#inventory-detail');
    if(!target){$('#view').insertAdjacentHTML('beforeend','<div id="inventory-detail"></div>');target=$('#inventory-detail');}
    const complete=result.items.every(item=>item.quantidade_contada!==null);
    target.innerHTML=`<div class="panel"><h2>Contagem do inventario #${id}</h2>${table(result.items,['produto','saldo_sistema','unidade_base'],row=>row.quantidade_contada===null?`<input class="count-input" data-product-id="${row.produto_id}" type="number" min="0" step=".001" required>`:esc(row.quantidade_contada))}<div class="quick-links">${complete?`<button class="primary" id="approve-inventory" type="button">Aprovar e ajustar saldos</button>`:`<button class="primary" id="save-inventory-count" type="button">Salvar contagem</button>`}</div></div>`;
    $('#save-inventory-count')?.addEventListener('click',async()=>{const items=[...target.querySelectorAll('.count-input')].map(input=>({produto_id:input.dataset.productId,quantidade:input.value}));if(items.some(item=>item.quantidade==='')){toast('Preencha a contagem de todos os produtos.');return;}try{await api('inventory_count',{method:'POST',body:JSON.stringify({id,itens:items})});toast('Contagem salva. Revise e aprove para registrar os ajustes.');inventoryDetail(id);}catch(error){toast(error.message);}});
    $('#approve-inventory')?.addEventListener('click',async()=>{if(!confirm('A aprovacao criara ajustes de estoque para as divergencias. Continuar?'))return;try{await api('inventory_approve',{method:'POST',body:JSON.stringify({id})});toast('Inventario aprovado.');load('inventory');}catch(error){toast(error.message);}});
  }catch(error){toast(error.message);}
}
function formatCell(key,value){if(value===null||value===undefined||value==='')return '—';if(['valor_estimado','preco_atual','custo_total','custo_porcao','custo_linha','valor','preco_unitario','desconto'].includes(key))return cash(value);if(['data_registro','data_compra','registrada_em','recebida_em','iniciado_em','criado_em'].includes(key))return dateTime(value);if(['data_inicio','data_fim','validade'].includes(key))return dateOnly(String(value).slice(0,10));if(['quantidade_liquida','quantidade','quantidade_planejada','quantidade_produzida','saldo_sistema','descarte','quantidade_preparada','quantidade_servida','sobra_reaproveitavel'].includes(key))return Number(value).toLocaleString('pt-BR');return esc(value);}
async function purchases(){
  const data=await api('purchases');$('#view').innerHTML=`<div class="panel"><div class="panel-head"><div><h2>Compras e recebimentos</h2><p class="muted">Abra as informações para consultar fornecedor, itens, valores, lotes e validade.</p></div><button class="add-btn" id="new-purchase">+ Registrar compra</button></div>${table(data.items,['data_compra','fornecedor','referencia','status','itens'],row=>`<div class="record-actions"><button class="small-btn" data-purchase-info="${row.id}">Informações</button>${row.status==='rascunho'?`<button class="small-btn" data-receive="${row.id}">Receber</button>`:''}</div>`)}</div><div id="purchase-detail"></div>`;
  $('#new-purchase').onclick=purchaseForm;document.querySelectorAll('[data-purchase-info]').forEach(button=>button.onclick=()=>purchaseDetail(button.dataset.purchaseInfo));document.querySelectorAll('[data-receive]').forEach(button=>button.onclick=async()=>{if(!confirm('Confirmar recebimento e atualizar estoque e histórico de preços?'))return;try{await api('purchase_receive',{method:'POST',body:JSON.stringify({id:button.dataset.receive})});toast('Compra recebida');purchases();}catch(error){toast(error.message);}});
}
async function purchaseDetail(id){try{const item=await api(`purchase_detail&id=${encodeURIComponent(id)}`);$('#purchase-detail').innerHTML=`<div class="panel"><div class="panel-head"><div><h2>Compra #${item.id} — ${esc(item.referencia||'Sem referência')}</h2><p class="muted">${esc(item.status)} · lançada por ${esc(item.usuario)}</p></div></div><div class="detail-grid">${detail('Fornecedor',item.fornecedor)}${detail('Telefone',item.telefone)}${detail('Data da compra',dateTime(item.data_compra))}${detail('Recebida em',dateTime(item.recebida_em))}${detail('Desconto do documento',cash(item.desconto_total))}${detail('Frete',cash(item.frete_total))}${detail('Total estimado',cash(item.total_estimado))}</div><h3>Itens</h3>${table(item.itens,['produto','quantidade','unidade','preco_unitario','desconto','lote','validade'])}<h3>Observações</h3><div class="text-block">${esc(item.observacoes||'Nenhuma observação.')}</div></div>`;$('#purchase-detail').scrollIntoView({behavior:'smooth',block:'start'});}catch(error){toast(error.message);}}
async function production(){const data=await api('production');$('#view').innerHTML=`<div class="panel"><div class="panel-head"><div><h2>Produção</h2><p class="muted">Consulte ficha, responsável, quantidades e observações de cada registro.</p></div><button class="add-btn" id="new-production">+ Planejar</button></div>${table(data.items,['registrada_em','ficha','quantidade_planejada','quantidade_produzida','unidade','turno','status'],row=>`<div class="record-actions"><button class="small-btn" data-production-info="${row.id}">Informações</button>${row.status==='planejada'?`<button class="small-btn" data-confirm-production="${row.id}">Confirmar</button>`:''}</div>`)}</div><div id="production-detail"></div>`;$('#new-production').onclick=productionForm;document.querySelectorAll('[data-production-info]').forEach(button=>button.onclick=()=>productionDetail(button.dataset.productionInfo));document.querySelectorAll('[data-confirm-production]').forEach(button=>button.onclick=async()=>{const quantity=prompt('Quantidade produzida:');if(!quantity)return;try{await api('production_confirm',{method:'POST',body:JSON.stringify({id:button.dataset.confirmProduction,quantidade_produzida:quantity})});toast('Produção confirmada; nenhuma baixa automática foi feita.');production();}catch(error){toast(error.message);}});}
async function productionDetail(id){try{const item=await api(`production_detail&id=${encodeURIComponent(id)}`);$('#production-detail').innerHTML=`<div class="panel"><div class="panel-head"><h2>Informações da produção #${item.id}</h2></div><div class="detail-grid">${detail('Ficha técnica',item.ficha)}${detail('Código da ficha',item.ficha_codigo)}${detail('Versão da ficha',item.ficha_versao)}${detail('Registrada em',dateTime(item.registrada_em))}${detail('Responsável',item.responsavel)}${detail('E-mail do responsável',item.responsavel_email)}${detail('Status',item.status)}${detail('Turno',item.turno)}${detail('Quantidade planejada',`${item.quantidade_planejada} ${item.unidade}`)}${detail('Quantidade realizada',item.quantidade_produzida===null?'Ainda não confirmada':`${item.quantidade_produzida} ${item.unidade}`)}${detail('Rendimento cadastrado',`${item.rendimento_total} ${item.unidade_rendimento}`)}</div><h3>Observações</h3><div class="text-block">${esc(item.observacoes||'Nenhuma observação.')}</div><p class="warning-note">A confirmação da produção não baixa ingredientes do estoque automaticamente.</p></div>`;$('#production-detail').scrollIntoView({behavior:'smooth',block:'start'});}catch(error){toast(error.message);}}
async function breakages(){const data=await api('breakages');records.breakages=data.items;$('#view').innerHTML=`<div class="panel"><h2>Registrar quebra patrimonial</h2><p class="muted">Em observações, informe também o nome da pessoa envolvida, se conhecido.</p><form id="breakage-form" class="form-grid"><label>Item<input name="item" required></label><label>Categoria<input name="categoria" required placeholder="Utensílio, equipamento…"></label><label>Quantidade<input name="quantidade" type="number" min=".001" step=".001" required></label><label>Unidade<input name="unidade" value="un" required></label><label>Local<input name="local"></label><label>Motivo<input name="motivo" required></label><label>Valor estimado<input name="valor_estimado" type="number" min="0" step=".01" value="0"></label><label>Reposição necessária<select name="reposicao_necessaria"><option value="0">Não</option><option value="1">Sim</option></select></label><label class="wide">Observações / pessoa envolvida<textarea name="observacoes" placeholder="Ex.: quebrado por Maria durante o preparo do almoço"></textarea></label><button class="primary wide">Registrar quebra</button></form></div><div class="panel"><h2>Histórico de quebras</h2>${table(data.items,['data_registro','item','categoria','quantidade','unidade','local','motivo','valor_estimado','usuario'],row=>`<button class="small-btn" data-breakage-info="${row.id}">Informações</button>`)}</div><div id="breakage-detail"></div>`;$('#breakage-form').onsubmit=async event=>{event.preventDefault();try{await api('breakages',{method:'POST',body:JSON.stringify(Object.fromEntries(new FormData(event.target)))});toast('Quebra registrada');breakages();}catch(error){toast(error.message);}};document.querySelectorAll('[data-breakage-info]').forEach(button=>button.onclick=()=>breakageDetail(button.dataset.breakageInfo));}
function breakageDetail(id){const item=(records.breakages||[]).find(row=>String(row.id)===String(id));if(!item)return;$('#breakage-detail').innerHTML=`<div class="panel"><div class="panel-head"><h2>Informações da quebra #${item.id}</h2></div><div class="detail-grid">${detail('Objeto',item.item)}${detail('Categoria',item.categoria)}${detail('Quantidade',`${item.quantidade} ${item.unidade}`)}${detail('Local',item.local)}${detail('Motivo',item.motivo)}${detail('Valor estimado',cash(item.valor_estimado))}${detail('Reposição necessária',Number(item.reposicao_necessaria)?'Sim':'Não')}${detail('Registrado por',item.usuario)}${detail('Data',dateTime(item.data_registro))}</div><h3>Observações e pessoa envolvida</h3><div class="text-block">${esc(item.observacoes||'Nenhuma observação informada.')}</div></div>`;$('#breakage-detail').scrollIntoView({behavior:'smooth',block:'start'});}
async function costSettings(){const data=await api('cost_settings');$('#view').innerHTML=`<div class="panel"><h2>Regras de custo</h2><p class="muted">Cadastre regras com nomes próprios e selecione qual método será aplicado às próximas compras recebidas. As regras não recalculam compras antigas.</p><form id="select-cost-rule" class="form-grid"><label class="wide">Regra ativa<select name="regra_id">${data.rules.map(rule=>`<option value="${rule.id}" ${String(rule.id)===String(data.regra_id)?'selected':''}>${esc(rule.nome)} — ${rule.metodo==='ultimo'?'último preço':'média ponderada'}${Number(rule.sistema)?' (padrão)':''}</option>`).join('')}</select></label><button class="primary wide">Usar esta regra</button></form><div id="cost-rules" class="rule-list">${data.rules.map(rule=>`<div class="rule-option"><div><strong>${esc(rule.nome)}</strong><br><small>${rule.metodo==='ultimo'?'Último preço efetivo recebido':'Média ponderada pelo volume comprado'}</small></div><span>${String(rule.id)===String(data.regra_id)?'Ativa':''}</span></div>`).join('')}</div></div><div class="panel"><h2>Cadastrar nova regra</h2><form id="new-cost-rule" class="form-grid"><label>Nome da regra<input name="nome" maxlength="80" required placeholder="Ex.: custo médio por fornecedor"></label><label>Método de cálculo<select name="metodo"><option value="ultimo">Último preço efetivo recebido</option><option value="media_ponderada">Média ponderada das compras</option></select></label><button class="primary wide">Cadastrar e ativar regra</button></form><p class="warning-note">A regra define o método de atualização do custo do produto. Valide com as planilhas antes de usar para decisões financeiras.</p></div>`;$('#select-cost-rule').onsubmit=async event=>{event.preventDefault();try{await api('cost_settings',{method:'POST',body:JSON.stringify(Object.fromEntries(new FormData(event.target)))});toast('Regra selecionada');costSettings();}catch(error){toast(error.message);}};$('#new-cost-rule').onsubmit=async event=>{event.preventDefault();try{await api('cost_settings',{method:'POST',body:JSON.stringify({modo:'criar',...Object.fromEntries(new FormData(event.target))})});toast('Regra cadastrada e ativada');costSettings();}catch(error){toast(error.message);}};}
function formatCell(key,value){if(value===null||value===undefined||value==='')return '—';if(['valor_estimado','preco_atual','custo_total','custo_porcao','custo_linha','valor','preco_unitario','desconto'].includes(key))return cash(value);if(['data_registro','data_compra','registrada_em','recebida_em','iniciado_em','criado_em'].includes(key))return dateTime(value);if(['data_inicio','data_fim','validade'].includes(key))return dateOnly(String(value).slice(0,10));if(['quantidade_liquida','quantidade','quantidade_planejada','quantidade_produzida','saldo_sistema','descarte','quantidade_preparada','quantidade_servida','sobra_reaproveitavel'].includes(key))return Number(value).toLocaleString('pt-BR');return esc(value);}
const tableBeforeRoadmapDetails=table;
table=(rows,columns,action)=>{let html=tableBeforeRoadmapDetails(rows,columns,action);const labels={data_compra:'Data da compra',recebida_em:'Recebida em',registrada_em:'Registrada em',iniciado_em:'Iniciada em',preco_unitario:'Preço unitário',desconto:'Desconto',lote:'Lote',validade:'Validade',itens:'Itens',referencia:'Referência',quantidade_planejada:'Planejada',quantidade_produzida:'Produzida',turno:'Turno',responsavel:'Responsável',ficha:'Ficha técnica',ficha_codigo:'Código da ficha',ficha_versao:'Versão',saldo_sistema:'Saldo no sistema',unidade_base:'Unidade base',local:'Local',reposicao_necessaria:'Reposição necessária',observacoes:'Observações',item:'Objeto',usuario:'Responsável',descarte:'Descarte',quantidade_preparada:'Preparada',quantidade_servida:'Servida',sobra_reaproveitavel:'Sobra reaproveitável'};for(const [key,label] of Object.entries(labels))html=html.replaceAll(`<th>${key}</th>`,`<th>${label}</th>`);return html;};
function toast(message){$('#toast').textContent=message;setTimeout(()=>$('#toast').textContent='',3000);}
